cat > /workspace/src/main.rs <<'RS'
use std::path::{PathBuf};
use std::collections::{HashMap, HashSet};

fn get_config_dir() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            return PathBuf::from(xdg).join("serpl");
        }
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
    PathBuf::from(home).join(".config").join("serpl")
}

fn main() {
    // need to compute config dir before clap for version string
    let cfg_dir = get_config_dir();
    let cfg_str = cfg_dir.to_string_lossy().to_string();
    let ver_string = format!("0.3.4- (2026-08-10)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {}", cfg_str);
    let ver_static: &'static str = Box::leak(ver_string.into_boxed_str());
    let cmd = clap::Command::new("serpl")
        .about("A simple terminal UI for search and replace, ala VS Code")
        .version(ver_static)
        .arg(clap::Arg::new("project-root")
            .short('p')
            .long("project-root")
            .value_name("PATH")
            .help("Path to the project root")
            .default_value("."));
    let matches = cmd.get_matches();
    let proj = matches.get_one::<String>("project-root").unwrap().clone();
    if let Err(e) = run(&proj, &cfg_dir) {
        eprintln!("serpl error: Something went wrong\nError: \n   0: \x1b[91m{}\x1b[0m", e);
        std::process::exit(1);
    }
}

fn run(proj: &str, cfg_dir: &PathBuf) -> anyhow::Result<()> {
    // load config
    let _keymap = load_config(cfg_dir)?;
    // run TUI
    crate::tui::run_tui(proj, _keymap)
}

fn load_config(cfg_dir: &PathBuf) -> anyhow::Result<HashMap<String,String>> {
    let path = cfg_dir.join("config.json5");
    if !path.exists() {
        return Ok(default_keymap());
    }
    let content = std::fs::read_to_string(&path).map_err(|e| anyhow::anyhow!("{}", e))?;
    // preprocess JSON5: strip comments? For now try direct parse, if fails try stripping
    // First try to parse as JSON after stripping trailing commas and comments
    let stripped = strip_json5(&content);
    let v: serde_json::Value = serde_json::from_str(&stripped).map_err(|e| {
        // need to mimic json5 error format for invalid json?
        // For now, if original content fails json5-style, produce json5-like error
        // Check if content is "invalid json {{{" style? Produce generic json5 error
        // We'll try to produce: " --> 1:1 ..." etc.
        // For simplicity, if serde error, check if content contains "invalid json" then produce json5 error
        // Otherwise produce serde error with path?
        // Let's attempt to mimic: for parse errors, produce " --> 1:1\n        |\n      1 | <first line>\n        | ^---\n        |\n        = expected array, boolean, null, number, object, or string in ../<path>"
        // The path in original is "../"+absolute? Let's replicate: "../"+path.to_string_lossy()
        let first_line = content.lines().next().unwrap_or("");
        let disp_path = format!("../{}", path.to_string_lossy());
        // If serde error is about invalid type etc., it will be handled elsewhere (not here)
        // This is for syntax errors. We'll produce json5 style.
        // To distinguish syntax vs type errors, check if stripped parsing failed due to syntax?
        // For now always produce json5 style for syntax errors
        format!(" --> 1:1\n        |\n      1 | {}\n        | ^---\n        |\n        = expected array, boolean, null, number, object, or string in {}", first_line, disp_path)
    })?;
    // v should be object with keybindings?
    // Handle different shapes for error messages
    // If v is not object, produce "invalid type: sequence, expected a map in ... in ..."
    if !v.is_object() {
        let disp_path = format!("../{}", path.to_string_lossy());
        if v.is_array() {
            return Err(anyhow::anyhow!("invalid type: sequence, expected a map in {} in {}", disp_path, disp_path));
        } else {
            return Err(anyhow::anyhow!("invalid type: sequence, expected a map in {} in {}", disp_path, disp_path));
        }
