            self.focus = Focus::ResultList;
        }
    }
    fn do_global_replace(&mut self) {
        // Replace all files (excluding excluded? Actually excluded files already filtered, so results are to be replaced)
        // Need to clone results to avoid borrow
        let files: Vec<PathBuf> = self.results.iter().map(|f| f.path.clone()).collect();
        for path in files {
            let _ = do_replace_file(&path, &self.search_text, &self.replace_text, self.search_mode, self.replace_mode);
        }
        self.refresh_search();
        // After global replace, focus goes to Search? Observed after h/l (global replace) focus went to Search. Implement.
        self.focus = Focus::Search;
    }
