    fn handle_replace_key(&mut self, key: KeyEvent) -> bool {
        if key.code == KeyCode::Char('n') && key.modifiers.contains(KeyModifiers::CONTROL) {
            self.replace_mode = self.replace_mode.next();
            return false;
        }
        // Ctrl-o is global ProcessReplace, already handled. But help says Replace: <C-o> when in Replace. That's the global binding, so already handled.
        // Enter in Replace? Probably no-op.
        if key.code == KeyCode::Enter {
            return false;
        }
        match key.code {
            KeyCode::Left => { if self.replace_cursor > 0 { self.replace_cursor -= 1; } },
            KeyCode::Right => { if self.replace_cursor < self.replace_text.len() { self.replace_cursor += 1; } },
            KeyCode::Home => { self.replace_cursor = 0; },
            KeyCode::End => { self.replace_cursor = self.replace_text.len(); },
            KeyCode::Backspace => {
                if self.replace_cursor > 0 && !self.replace_text.is_empty() {
                    let mut new_cursor = self.replace_cursor - 1;
                    while new_cursor > 0 && !self.replace_text.is_char_boundary(new_cursor) {
                        new_cursor -= 1;
                    }
                    self.replace_text.remove(new_cursor);
                    self.replace_cursor = new_cursor;
                }
            },
            KeyCode::Delete => {
                if self.replace_cursor < self.replace_text.len() {
                    self.replace_text.remove(self.replace_cursor);
                }
            },
            KeyCode::Char(c) => {
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match c {
                        'w' | 'W' => {
                            if self.replace_cursor > 0 {
                                let s = &self.replace_text[..self.replace_cursor];
                                if let Some(pos) = s.rfind(' ') {
                                    let trimmed = s.trim_end();
                                    if trimmed.is_empty() {
                                        self.replace_text.clear();
                                        self.replace_cursor = 0;
                                    } else {
                                        if let Some(pos2) = trimmed.rfind(' ') {
                                            let new_len = pos2 + 1;
                                            self.replace_text.truncate(new_len);
                                            self.replace_cursor = new_len;
                                        } else {
                                            self.replace_text.clear();
                                            self.replace_cursor = 0;
                                        }
                                    }
                                } else {
                                    self.replace_text.clear();
                                    self.replace_cursor = 0;
                                }
                            }
                            return false;
                        },
                        'u' | 'U' => { self.replace_text.clear(); self.replace_cursor = 0; return false; },
                        'k' | 'K' => { self.replace_text.truncate(self.replace_cursor); return false; },
                        'a' | 'A' => { self.replace_cursor = 0; return false; },
                        'e' | 'E' => { self.replace_cursor = self.replace_text.len(); return false; },
                        _ => return false,
