    fn next_file(&mut self) {
        if self.results.is_empty() { return; }
        let next = match self.selected_file {
            None => 0,
            Some(i) => (i + 1) % self.results.len(),
        };
        self.selected_file = Some(next);
        self.preview_line = 0;
        self.preview_scroll = 0;
        // As observed, j in RL switches focus to Preview. Implement that toggle?
        // For now, switch focus to Preview after selecting file (to match observed).
        self.focus = Focus::Preview;
    }
    fn prev_file(&mut self) {
        if self.results.is_empty() { return; }
        let prev = match self.selected_file {
            None => self.results.len() - 1,
            Some(0) => self.results.len() - 1,
            Some(i) => i - 1,
        };
        self.selected_file = Some(prev);
        self.preview_line = 0;
        self.preview_scroll = 0;
        self.focus = Focus::Preview;
    }
    fn top_file(&mut self) {
        if self.results.is_empty() { return; }
        self.selected_file = Some(0);
        self.preview_line = 0;
        self.preview_scroll = 0;
        self.focus = Focus::Preview;
    }
    fn bottom_file(&mut self) {
        if self.results.is_empty() { return; }
        self.selected_file = Some(self.results.len() - 1);
        self.preview_line = 0;
        self.preview_scroll = 0;
        self.focus = Focus::Preview;
    }
    fn delete_file(&mut self) {
        if let Some(idx) = self.selected_file {
            if idx < self.results.len() {
                let path = self.results[idx].path.clone();
                self.excluded_files.insert(path);
                self.refresh_search();
                // After delete, focus goes to Preview? Observed after d in RL, focus went to Preview. Implement.
                self.focus = Focus::Preview;
                // If results now empty, selected_file None, else keep?
                if self.results.is_empty() {
                    self.selected_file = None;
                } else if idx >= self.results.len() {
                    self.selected_file = Some(self.results.len() - 1);
                }
            }
        }
    }
    fn replace_file(&mut self) {
        if let Some(idx) = self.selected_file {
            if idx >= self.results.len() { return; }
            let file = &self.results[idx];
            // perform replace for this file (all matches, unless excluded lines? But file selected means no excluded lines for this file? Actually excluded lines are per-line, but file selected means replace all lines in file)
            if let Err(e) = do_replace_file(&file.path, &self.search_text, &self.replace_text, self.search_mode, self.replace_mode) {
                // ignore? Or show error? For now ignore.
                let _ = e;
            }
            // After replace, remove from results (as observed)
            let path = file.path.clone();
            // Instead of excluded, just refresh (file will have no matches, so disappear)
            self.refresh_search();
            self.focus = Focus::Preview;
            // Keep selection? After replace, results empty or next file? Original after r in RL went to Preview with empty list. Good.
        }
    }
    fn next_line(&mut self) {
        // Navigate preview lines: if no file selected, do nothing? Or select first file?
        // Observed: j in Preview with no file? Actually Preview with no file shows empty, j does nothing? For now, if no file, do nothing.
        // If file selected, move preview_line to next match (within file) and switch focus to ResultList? As observed, j in Preview goes to RL.
        // Implement toggle: after moving, switch focus to ResultList.
        if let Some(fidx) = self.selected_file {
            if fidx >= self.results.len() { return; }
            let len = self.results[fidx].matches.len();
            if len == 0 { return; }
            self.preview_line = (self.preview_line + 1) % len;
            self.focus = Focus::ResultList;
        } else {
            // No file selected, select first file? Like RL's j?
            self.next_file();
        }
    }
    fn prev_line(&mut self) {
        if let Some(fidx) = self.selected_file {
            if fidx >= self.results.len() { return; }
            let len = self.results[fidx].matches.len();
            if len == 0 { return; }
            if self.preview_line == 0 {
                self.preview_line = len - 1;
            } else {
                self.preview_line -= 1;
            }
            self.focus = Focus::ResultList;
        } else {
            self.prev_file();
        }
    }
    fn top_line(&mut self) {
        if self.selected_file.is_some() {
            self.preview_line = 0;
            self.focus = Focus::ResultList;
        }
    }
    fn bottom_line(&mut self) {
        if let Some(fidx) = self.selected_file {
            if fidx < self.results.len() {
                let len = self.results[fidx].matches.len();
                if len > 0 {
                    self.preview_line = len - 1;
                }
                self.focus = Focus::ResultList;
            }
        }
    }
    fn delete_line(&mut self) {
        if let Some(fidx) = self.selected_file {
            if fidx >= self.results.len() { return; }
            let file = &self.results[fidx];
            if self.preview_line >= file.matches.len() { return; }
            let line_no = file.matches[self.preview_line].line_no;
            self.excluded_lines.insert((file.path.clone(), line_no));
            self.refresh_search();
            self.focus = Focus::ResultList;
        }
    }
    fn replace_line(&mut self) {
        if let Some(fidx) = self.selected_file {
            if fidx >= self.results.len() { return; }
            let file = &self.results[fidx].clone(); // clone to avoid borrow?
            // Actually need to replace only selected line, not whole file. How to do single line replace?
            // For now, if preview_line corresponds to a line, replace only that line's matches.
            if self.preview_line >= file.matches.len() { return; }
            let line_no = file.matches[self.preview_line].line_no;
            if let Err(_) = do_replace_line(&file.path, line_no, &self.search_text, &self.replace_text, self.search_mode, self.replace_mode) {
            }
            self.refresh_search();
            self.focus = Focus::ResultList;
        }
    }
    fn do_global_replace(&mut self) {
        // Replace all files (excluding excluded? Actually excluded files already filtered, so results are to be replaced)
        // Need to clone results to avoid borrow
        let files: Vec<PathBuf> = self.results.iter().map(|f| f.path.clone()).collect();
        for path in files {
            let _ = do_replace_file(&path, &self.search_text, &self.replace_text, self.search_mode, self.replace_mode);
        }
        self.refresh_search();
        // After global replace, focus goes to Search? Observed after h/l (global replace) focus went to Search. Implement.
        self.focus = Focus::Search;
    }
}

