        KeyCode::End => {
            if key.modifiers.is_empty() { return "<End>".to_string(); }
        },
        KeyCode::PageUp => {
            if key.modifiers.is_empty() { return "<PageUp>".to_string(); }
        },
        KeyCode::PageDown => {
            if key.modifiers.is_empty() { return "<PageDown>".to_string(); }
        },
        KeyCode::Backspace => {
            if key.modifiers.is_empty() { return "<Backspace>".to_string(); }
        },
        KeyCode::Delete => {
            if key.modifiers.is_empty() { return "<Delete>".to_string(); }
        },
        KeyCode::Insert => {
            if key.modifiers.is_empty() { return "<Insert>".to_string(); }
        },
        KeyCode::F(n) => {
            if key.modifiers.is_empty() { return format!("<F{}>", n); }
        },
        KeyCode::Char(c) => {
            if key.modifiers.is_empty() {
                return c.to_string();
            }
            // With modifiers: build "<Ctrl-...>" etc.
            let mut mods = Vec::new();
            if key.modifiers.contains(KeyModifiers::CONTROL) { mods.push("Ctrl"); }
            if key.modifiers.contains(KeyModifiers::ALT) { mods.push("Alt"); }
            if key.modifiers.contains(KeyModifiers::SHIFT) {
                // For Char with Shift (uppercase), should we include Shift? Original accepts "<Shift-a>" for Shift+a. Crossterm for Shift+a gives Char('A') with Shift? Or Char('a') with Shift? Need to handle.
                // If c is uppercase and mods only Shift, then config "<Shift-a>" should match pressing Shift+a (which gives 'A'). Our conversion for Char('A') with Shift would give "<Shift-A>" (with uppercase). Lowercased comparison will match "<shift-a>"? Good (case-insensitive).
                mods.push("Shift");
            }
            if mods.is_empty() {
                return c.to_string();
            }
            // For Space? Char(' ') with no modifiers is " " (single space). With Ctrl? "<Ctrl-Space>"? Crossterm for Ctrl+Space gives Char(' ') with Ctrl? Or KeyCode::Char(' ')? We'll handle.
            // Key name for char: if c == ' ', use "Space"? Original accepts "<Space>" and " " (single space) as valid. For Ctrl+Space, config is "<Ctrl-Space>" (as observed valid). Crossterm for Ctrl+Space: code Char(' ') with Ctrl? Our conversion would give "<Ctrl- >" (with space), not "<Ctrl-Space>". Need to map space to "Space" when with modifiers.
            let key_name = if c == ' ' { "Space".to_string() } else { c.to_string() };
            return format!("<{}-{}>", mods.join("-"), key_name);
        },
        KeyCode::Null => {},
        _ => {},
    }
    // Fallback: for modified named keys (e.g., Ctrl+Up, Alt+Enter, etc.)
    // Build "<Mods-Key>"
    let mut mods = Vec::new();
    if key.modifiers.contains(KeyModifiers::CONTROL) { mods.push("Ctrl"); }
    if key.modifiers.contains(KeyModifiers::ALT) { mods.push("Alt"); }
    if key.modifiers.contains(KeyModifiers::SHIFT) { mods.push("Shift"); }
    let base = match key.code {
        KeyCode::Tab => "Tab",
        KeyCode::BackTab => "Backtab",
        KeyCode::Enter => "Enter",
        KeyCode::Esc => "Esc",
        KeyCode::Left => "Left",
        KeyCode::Right => "Right",
        KeyCode::Up => "Up",
        KeyCode::Down => "Down",
        KeyCode::Home => "Home",
        KeyCode::End => "End",
        KeyCode::PageUp => "PageUp",
        KeyCode::PageDown => "PageDown",
        KeyCode::Backspace => "Backspace",
        KeyCode::Delete => "Delete",
        KeyCode::Insert => "Insert",
        KeyCode::F(n) => return if mods.is_empty() { format!("<F{}>", n) } else { format!("<{}-F{}>", mods.join("-"), n) },
        KeyCode::Char(c) => {
            if c == ' ' { "Space" } else { return format!("<{}-{}>", mods.join("-"), c) }
        },
        _ => return "".to_string(),
    };
    if mods.is_empty() {
        return format!("<{}>", base);
    } else {
        return format!("<{}-{}>", mods.join("-"), base);
    }
}

// Search engine
fn search_files(proj: &PathBuf, pattern: &str, mode: SearchMode) -> Vec<FileResult> {
    use ignore::WalkBuilder;
    let mut results = Vec::new();
    // Build walker with defaults (hidden, gitignore, etc.)
    let mut builder = WalkBuilder::new(proj);
    builder.hidden(true);
    // builder.require_git(true) is default? Ensure gitignore only if git repo? Default is require_git(true)? Let's keep defaults (which should match original).
    // Also skip symlinks? WalkBuilder by default does not follow symlinks (follow_links(false)). Good.
    // Also need to handle binary? We'll filter later.
    let walker = builder.build();
    // For regex mode, compile regex once
    let regex_opt = if mode == SearchMode::Regex {
        match regex::Regex::new(pattern) {
            Ok(r) => Some(r),
            Err(_) => return Vec::new(), // invalid regex -> no results (as observed)
        }
    } else { None };

    for entry in walker {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        // Skip dirs, symlinks? entry.file_type? If symlink, skip? WalkBuilder without follow_links will list symlink itself, but we should skip symlinks (as observed link.txt ignored).
        if let Ok(ft) = entry.file_type() {
            if ft.is_dir() { continue; }
            if ft.is_symlink() { continue; }
        } else { continue; }
        // Skip hidden? Already via builder, but also skip files starting with .? Builder does.
        let path = entry.path().to_path_buf();
        // Skip .git dir? Builder handles? It will skip .git? Actually hidden includes .git? .git is hidden? It starts with ., so yes. Good.
        // Read file, skip binary (null byte) and non-utf8? For now, read as bytes, check null, then convert to string lossy? Original probably skips binary (null) and reads utf8? Let's implement: read bytes, if contains 0, skip. Else convert to utf8 (if invalid, skip? Or lossy? For now skip if invalid).
        let bytes = match std::fs::read(&path) {
            Ok(b) => b,
            Err(_) => continue,
        };
        if bytes.contains(&0) {
            continue;
        }
        let content = match String::from_utf8(bytes) {
            Ok(s) => s,
            Err(_) => continue, // skip non-utf8
        };
        // Search each line
        let mut file_matches = Vec::new();
        for (idx, line) in content.lines().enumerate() {
            let line_no = idx + 1;
            let ranges = find_matches_in_line(line, pattern, mode, &regex_opt);
            if !ranges.is_empty() {
                // For whole word etc., ranges already filtered
                file_matches.push(FileMatch {
                    path: path.clone(),
                    rel: display_rel(&proj, &path),
                    line_no,
                    line_content: line.to_string(),
                    match_ranges: ranges,
                });
            }
        }
        if !file_matches.is_empty() {
            let total: usize = file_matches.iter().map(|m| m.match_ranges.len()).sum();
            results.push(FileResult {
                path: path.clone(),
                rel: display_rel(&proj, &path),
                matches: file_matches,
                total_count: total,
            });
        }
    }
    results
}

fn display_rel(proj: &PathBuf, path: &PathBuf) -> String {
    // Relative to proj, with forward slashes? Original shows "sub/c.txt" for subdir, "a.txt" for top. Good.
    if let Ok(rel) = path.strip_prefix(proj) {
        return rel.to_string_lossy().replace("\\", "/");
    }
    // If proj is "." and path is "./a.txt"? Need to handle.
    // Fallback: file name?
    path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| path.to_string_lossy().to_string())
}

fn find_matches_in_line(line: &str, pattern: &str, mode: SearchMode, regex_opt: &Option<regex::Regex>) -> Vec<(usize, usize)> {
    if pattern.is_empty() { return Vec::new(); }
    match mode {
        SearchMode::Simple => {
            // case-insensitive fixed
            let line_lower = line.to_lowercase();
            let pat_lower = pattern.to_lowercase();
            let mut res = Vec::new();
            let mut start = 0;
            while let Some(pos) = line_lower[start..].find(&pat_lower) {
                let s = start + pos;
                let e = s + pattern.len(); // careful: pattern len in bytes vs chars? For ascii, same. For unicode, lowercasing may change len? Simplify for ascii? For unicode, use char? Original likely handles unicode? For now assume ascii (pattern len same).
                // Need byte indices in original line (not lowercased). Since lowercasing may change byte len for unicode, but for ascii it's same. We'll use s..e as byte indices (valid for ascii).
                // For safety, ensure boundaries
                if s <= line.len() && e <= line.len() {
                    res.push((s, e));
                }
                start = s + pat_lower.len().max(1);
                if start >= line.len() { break; }
            }
            res
        },
        SearchMode::MatchCase => {
            let mut res = Vec::new();
            let mut start = 0;
            while let Some(pos) = line[start..].find(pattern) {
                let s = start + pos;
                let e = s + pattern.len();
                res.push((s, e));
                start = e.max(start+1);
                if start >= line.len() { break; }
            }
            res
        },
        SearchMode::MatchWholeWord => {
            // case-insensitive whole word: use regex with \b and case-insensitive?
            // Build regex: (?i)\b<escaped>\b
            let esc = regex::escape(pattern);
            let re_str = format!("(?i)\\b{}\\b", esc);
            let re = regex::Regex::new(&re_str).unwrap();
            re.find_iter(line).map(|m| (m.start(), m.end())).collect()
        },
        SearchMode::MatchCaseWholeWord => {
            let esc = regex::escape(pattern);
            let re_str = format!("\\b{}\\b", esc);
            let re = regex::Regex::new(&re_str).unwrap();
            re.find_iter(line).map(|m| (m.start(), m.end())).collect()
        },
        SearchMode::Regex => {
            if let Some(re) = regex_opt {
                // Need to handle invalid? Already handled (return empty). For valid, find all.
                // Regex is case-sensitive (no (?i) unless user includes)
                re.find_iter(line).map(|m| (m.start(), m.end())).collect()
            } else { Vec::new() }
        },
    }
}

// Replace logic
fn preserve_case(original: &str, replacement: &str) -> String {
    // As observed: Hello->Bye, HELLO->BYE, hello->bye, HeLLo->Bye (capitalized? Or first upper rest lower? HeLLo has first upper, rest mixed, result Bye (capitalized)).
    // Rules: if original is all upper -> upper, all lower -> lower, capitalized (first upper, rest lower) -> capitalized, else? For HeLLo (first upper, rest mixed), result Bye (capitalized). So else -> capitalized? Or lower? Let's test more: what about "hELLO" (first lower, rest upper)? Need to test preserve case for that.
    // For now implement: if original.chars().all(|c| c.is_uppercase()) -> replacement.to_uppercase()
    // else if original.chars().all(|c| c.is_lowercase()) -> replacement.to_lowercase()
    // else if original.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) && original[1..].chars().all(|c| c.is_lowercase()) -> capitalized (first upper rest lower)
    // else -> capitalized? Or as is? Let's check HeLLo: first 'H' upper, rest "eLLo" not all lower (has 'L'), so else -> capitalized (Bye). Good.
    // What about single char? e.g., "H" (upper) -> upper, "h" (lower) -> lower. Good.
    if original.is_empty() { return replacement.to_string(); }
    // Check if original contains only cased letters? For non-letters? e.g., "HELLO123"? all upper? Digits are neither, but is_uppercase for digits is false? Actually char::is_uppercase for '1' is false, is_lowercase false. So all() would fail. Need to consider only alphabetic? For simplicity, check only alphabetic chars.
    let letters: Vec<char> = original.chars().filter(|c| c.is_alphabetic()).collect();
    if letters.is_empty() {
        return replacement.to_string();
    }
    if letters.iter().all(|c| c.is_uppercase()) {
        return replacement.to_uppercase();
    }
    if letters.iter().all(|c| c.is_lowercase()) {
        return replacement.to_lowercase();
    }
    // Capitalized? First letter upper, rest lower?
    if letters[0].is_uppercase() && letters[1..].iter().all(|c| c.is_lowercase()) {
        // capitalize replacement: first upper rest lower?
        let mut chars = replacement.chars();
        if let Some(first) = chars.next() {
            let mut s = first.to_uppercase().to_string();
            s.push_str(&chars.as_str().to_lowercase());
            return s;
        } else {
            return replacement.to_string();
        }
    }
    // Else? For HeLLo, first upper but rest not all lower, so fallback to capitalized? Let's do capitalized.
    // Actually HeLLo's letters: H,e,L,L,o -> first upper, rest not all lower (L upper), so falls here. Return capitalized.
    let mut chars = replacement.chars();
    if let Some(first) = chars.next() {
        let mut s = first.to_uppercase().to_string();
        s.push_str(&chars.as_str().to_lowercase());
        return s;
    }
    replacement.to_string()
}

fn do_replace_file(path: &PathBuf, search: &str, replace: &str, smode: SearchMode, rmode: ReplaceMode) -> anyhow::Result<()> {
    if search.is_empty() { return Ok(()); }
    let content = std::fs::read_to_string(path)?;
    let mut new_lines = Vec::new();
    for line in content.lines() {
        // Check if line has matches?
        let ranges = find_matches_in_line(line, search, smode, &match_regex_opt(search, smode));
        if ranges.is_empty() {
            new_lines.push(line.to_string());
            continue;
        }
        match rmode {
            ReplaceMode::DeleteLine => {
                // skip line (delete)
                continue;
            },
            ReplaceMode::Simple => {
                // replace all occurrences with replace string (need to handle case for Simple? Simple is case-insensitive, but replacement is as is? For Simple, replacement is literal, no preserve. How to replace case-insensitively? Need to replace each match's text with replace string (as is). For Simple, search is case-insensitive, so "Hello" match should be replaced with "BYE" as is (not preserving). Our earlier test with Simple "hello" -> "bye" on "Hello HELLO hello HeLLo" gave "Hellobye"? Actually that test was with Simple? Let's see: we had search hello (Simple, case-insensitive) and replace bye (Simple). File "Hello HELLO hello HeLLo" -> preview showed "Hellobye HELLObye hellobye HeLLobye" (each original + bye). That means each match replaced with "bye" as is (lowercase), regardless of original case. Good. So Simple replace is literal.
                let new_line = replace_all_fixed(line, search, replace, smode);
                new_lines.push(new_line);
            },
            ReplaceMode::PreserveCase => {
                // replace each match with preserve_case(original_match, replace)
                let new_line = replace_all_preserve(line, search, replace, smode);
                new_lines.push(new_line);
            },
        }
    }
    // Handle DeleteLine for regex? Already.
    // Write back, preserving trailing newline? Original file ends with \n. content.lines() strips newline, need to add back.
    let mut out = new_lines.join("\n");
    if content.ends_with('\n') {
        out.push('\n');
    }
    std::fs::write(path, out)?;
    Ok(())
}

fn match_regex_opt(search: &str, smode: SearchMode) -> Option<regex::Regex> {
    if smode == SearchMode::Regex {
        regex::Regex::new(search).ok()
    } else { None }
}

fn replace_all_fixed(line: &str, search: &str, replace: &str, smode: SearchMode) -> String {
    match smode {
        SearchMode::Simple => {
            // case-insensitive: need to find matches and replace
            let ranges = find_matches_in_line(line, search, smode, &None);
            if ranges.is_empty() { return line.to_string(); }
            let mut res = String::new();
            let mut last = 0;
            for (s,e) in ranges {
                res.push_str(&line[last..s]);
                res.push_str(replace);
                last = e;
            }
            res.push_str(&line[last..]);
            res
        },
        SearchMode::MatchCase => {
            line.replace(search, replace)
        },
        SearchMode::MatchWholeWord => {
            let esc = regex::escape(search);
            let re = regex::Regex::new(&format!("(?i)\\b{}\\b", esc)).unwrap();
            re.replace_all(line, replace).to_string()
        },
        SearchMode::MatchCaseWholeWord => {
            let esc = regex::escape(search);
            let re = regex::Regex::new(&format!("\\b{}\\b", esc)).unwrap();
            re.replace_all(line, replace).to_string()
        },
        SearchMode::Regex => {
            if let Ok(re) = regex::Regex::new(search) {
                re.replace_all(line, replace).to_string()
            } else { line.to_string() }
        },
    }
}

fn replace_all_preserve(line: &str, search: &str, replace: &str, smode: SearchMode) -> String {
    // For each match, preserve case
    let ranges = find_matches_in_line(line, search, smode, &match_regex_opt(search, smode));
    if ranges.is_empty() { return line.to_string(); }
    let mut res = String::new();
    let mut last = 0;
    for (s,e) in ranges {
        res.push_str(&line[last..s]);
        let orig = &line[s..e];
        res.push_str(&preserve_case(orig, replace));
        last = e;
    }
    res.push_str(&line[last..]);
    res
}

fn do_replace_line(path: &PathBuf, line_no: usize, search: &str, replace: &str, smode: SearchMode, rmode: ReplaceMode) -> anyhow::Result<()> {
    if search.is_empty() { return Ok(()); }
    let content = std::fs::read_to_string(path)?;
    let lines: Vec<&str> = content.lines().collect();
    let mut new_lines = Vec::new();
    for (idx, line) in lines.iter().enumerate() {
        let cur_no = idx + 1;
        if cur_no != line_no {
            new_lines.push(line.to_string());
            continue;
        }
        // This is target line
        let ranges = find_matches_in_line(line, search, smode, &match_regex_opt(search, smode));
        if ranges.is_empty() {
            new_lines.push(line.to_string());
            continue;
        }
        match rmode {
            ReplaceMode::DeleteLine => {
                // skip (delete line)
                continue;
            },
            ReplaceMode::Simple => {
                new_lines.push(replace_all_fixed(line, search, replace, smode));
            },
            ReplaceMode::PreserveCase => {
                new_lines.push(replace_all_preserve(line, search, replace, smode));
            },
        }
    }
    let mut out = new_lines.join("\n");
    if content.ends_with('\n') {
        // Need to handle deleted last line? If last line deleted and original ended with newline, should we keep newline? For simplicity, if new_lines empty, out empty. Else join + newline if original had newline and new_lines not empty? Actually if last line deleted, file should end without extra newline? Let's just add newline if original had newline and new_lines not empty.
        if !new_lines.is_empty() {
            out.push('\n');
        } else {
            // empty file, no newline? Keep as empty?
        }
    }
    std::fs::write(path, out)?;
    Ok(())
}

